// ============================================================
// 06_pangi_catalog_sync — Construcción de SQL
// ------------------------------------------------------------
// Toma las respuestas de los 3 endpoints públicos de Pangi y
// arma las sentencias de upsert. No escribe nada: solo construye.
//
// FUENTES (una llamada a speciality trae los 3 idiomas):
//   /api/common/speciality?lang=en   → especialidades + procedimientos
//   /api/common/countries            → catálogo curado de ciudades
//   /api/common/available-locations  → ciudades con médicos reales
// ============================================================

const runAt = new Date().toISOString();
const source = ($execution && $execution.mode === 'test') ? 'manual' : 'schedule';

// ── Sanitizadores ──
const q = (v) => (v === null || v === undefined || v === '')
  ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const qi = (v) => { const n = parseInt(v, 10); return Number.isFinite(n) ? String(n) : 'NULL'; };
const qb = (v) => (v === true || v === 'true') ? 'TRUE' : 'FALSE';

// sub_speciality, states y cities llegan como STRING con JSON adentro.
// Proctology llega como array real. Hay que soportar ambos.
const parseArr = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
  }
  return [];
};

const fail = (msg) => [{ json: { valid: false, runAt, source, error: msg,
  sqlLogFail: "INSERT INTO pangi_catalog_sync_log " +
    "(started_at, finished_at, status, trigger_source, error_message) VALUES (" +
    q(runAt) + "::timestamptz, NOW(), 'failed', " + q(source) + ", " + q(msg) + ");" } }];

// ── 1. Leer las tres respuestas ──
let rSpec, rCountries, rLocations;
try {
  rSpec      = $('🌐 API — Especialidades').first().json;
  rCountries = $('🌐 API — Países').first().json;
  rLocations = $('🌐 API — Ubicaciones Activas').first().json;
} catch (e) {
  return fail('No se pudieron leer las respuestas del API: ' + e.message);
}

const specData = (rSpec && Array.isArray(rSpec.data)) ? rSpec.data : [];
const cntData  = (rCountries && Array.isArray(rCountries.data)) ? rCountries.data : [];
const locData  = (rLocations && Array.isArray(rLocations.data)) ? rLocations.data : [];

// Guarda de plausibilidad: Pangi tiene 22 especialidades. Si llegan
// muchas menos, algo salió mal y NO se debe tocar el catálogo local.
const MIN_SPECIALTIES = 15;
if (specData.length < MIN_SPECIALTIES) {
  return fail('Respuesta implausible: ' + specData.length +
              ' especialidades (mínimo esperado ' + MIN_SPECIALTIES + ')');
}
if (cntData.length === 0 && locData.length === 0) {
  return fail('Ambas fuentes de ciudades vinieron vacías');
}

// ── 2. Especialidades ──
const specRows = [];
const procRows = [];
const seenProc = new Set();

for (const s of specData) {
  if (!s || !s._id || !s.name) continue;

  specRows.push('(' + [
    q(s._id), q(s.name), q(s.name_es), q(s.name_pt),
    qb(s.is_visible), qi(s.allow_number_of_procedure) === 'NULL' ? '1' : qi(s.allow_number_of_procedure),
    q(s.doc_en), q(s.doc_es), q(s.doc_pt), q(s.logo), q(runAt) + '::timestamptz'
  ].join(', ') + ')');

  // Procedimientos: arreglos PARALELOS alineados por posición.
  // Dental tiene 48 en inglés y 0 traducidos → name_es/name_pt en NULL.
  const en = parseArr(s.sub_speciality);
  const es = parseArr(s.sub_speciality_es);
  const pt = parseArr(s.sub_speciality_pt);

  for (let i = 0; i < en.length; i++) {
    const name = en[i];
    if (typeof name !== 'string' || !name) continue;
    // Dedup: ON CONFLICT no puede afectar la misma fila dos veces
    // dentro de un mismo INSERT.
    const key = s._id + '||' + name;
    if (seenProc.has(key)) continue;
    seenProc.add(key);

    procRows.push('(' + [
      q(s._id), String(i), q(name),
      q(es[i] !== undefined ? es[i] : null),
      q(pt[i] !== undefined ? pt[i] : null),
      q(runAt) + '::timestamptz'
    ].join(', ') + ')');
  }
}

if (specRows.length === 0) return fail('Ninguna especialidad válida tras el parseo');
if (procRows.length === 0) return fail('Ningún procedimiento válido tras el parseo');

// ── 3. Ciudades: unión de las dos fuentes ──
// countries           → in_catalog  (catálogo curado)
// available-locations → has_doctors (dónde hay médicos de verdad)
const cityMap = new Map();
const putCity = (code, cname, city, flag) => {
  if (!code || !city) return;
  const key = code + '||' + city;
  const prev = cityMap.get(key) || { code, cname, city, in_catalog: false, has_doctors: false };
  prev[flag] = true;
  if (cname) prev.cname = cname;
  cityMap.set(key, prev);
};

for (const c of cntData) {
  if (!c || !c.code) continue;
  for (const city of parseArr(c.cities)) {
    if (typeof city === 'string' && city) putCity(c.code, c.name, city, 'in_catalog');
  }
}
for (const l of locData) {
  const code = l && l.country ? l.country.code : null;
  const cname = l && l.country ? l.country.name : null;
  for (const city of (Array.isArray(l.cities) ? l.cities : [])) {
    if (typeof city === 'string' && city) putCity(code, cname, city, 'has_doctors');
  }
}

const cityRows = [];
for (const c of cityMap.values()) {
  cityRows.push('(' + [
    q(c.code), q(c.cname || c.code), q(c.city),
    qb(c.in_catalog), qb(c.has_doctors), q(runAt) + '::timestamptz'
  ].join(', ') + ')');
}
if (cityRows.length === 0) return fail('Ninguna ciudad válida tras el parseo');

// ── 4. Sentencias ──
const sqlSpecialties =
  'INSERT INTO pangi_specialties ' +
  '(pangi_id, name, name_es, name_pt, is_visible, allow_number_of_procedure, ' +
  ' doc_en, doc_es, doc_pt, logo, synced_at) VALUES\n' +
  specRows.join(',\n') + '\n' +
  'ON CONFLICT (pangi_id) DO UPDATE SET ' +
  'name = EXCLUDED.name, name_es = EXCLUDED.name_es, name_pt = EXCLUDED.name_pt, ' +
  'is_visible = EXCLUDED.is_visible, ' +
  'allow_number_of_procedure = EXCLUDED.allow_number_of_procedure, ' +
  'doc_en = EXCLUDED.doc_en, doc_es = EXCLUDED.doc_es, doc_pt = EXCLUDED.doc_pt, ' +
  'logo = EXCLUDED.logo, synced_at = EXCLUDED.synced_at;';

const sqlProcedures =
  'INSERT INTO pangi_procedures ' +
  '(specialty_pangi_id, position, name, name_es, name_pt, synced_at) VALUES\n' +
  procRows.join(',\n') + '\n' +
  'ON CONFLICT (specialty_pangi_id, name) DO UPDATE SET ' +
  'position = EXCLUDED.position, name_es = EXCLUDED.name_es, ' +
  'name_pt = EXCLUDED.name_pt, synced_at = EXCLUDED.synced_at;';

const sqlCities =
  'INSERT INTO pangi_cities ' +
  '(country_code, country_name, city, in_catalog, has_doctors, synced_at) VALUES\n' +
  cityRows.join(',\n') + '\n' +
  'ON CONFLICT (country_code, city) DO UPDATE SET ' +
  'country_name = EXCLUDED.country_name, in_catalog = EXCLUDED.in_catalog, ' +
  'has_doctors = EXCLUDED.has_doctors, synced_at = EXCLUDED.synced_at;';

// Limpieza + bitácora en UNA sola sentencia (CTE), para no depender
// de que el nodo Postgres acepte múltiples sentencias.
// Las especialidades NO se borran aquí: is_visible ya las oculta y
// borrarlas cascadearía procedimientos dentro del mismo statement.
const sqlCleanupAndLog =
  'WITH del_proc AS (' +
  '  DELETE FROM pangi_procedures WHERE synced_at < ' + q(runAt) + '::timestamptz RETURNING 1' +
  '), del_city AS (' +
  '  DELETE FROM pangi_cities WHERE synced_at < ' + q(runAt) + '::timestamptz RETURNING 1' +
  ') INSERT INTO pangi_catalog_sync_log ' +
  '(started_at, finished_at, status, specialties_seen, procedures_seen, ' +
  ' cities_seen, rows_deleted, trigger_source) ' +
  'SELECT ' + q(runAt) + '::timestamptz, NOW(), \'ok\', ' +
  specRows.length + ', ' + procRows.length + ', ' + cityRows.length + ', ' +
  '(SELECT COUNT(*) FROM del_proc) + (SELECT COUNT(*) FROM del_city), ' +
  q(source) + ';';

return [{ json: {
  valid: true, runAt, source,
  counts: { specialties: specRows.length, procedures: procRows.length, cities: cityRows.length },
  sqlSpecialties, sqlProcedures, sqlCities, sqlCleanupAndLog
} }];
